/* School Dashboard - namespace sch-dash */
.sch-dash {
    --sch-primary: #4b6c9e;
    --sch-primary-light: #6b8bb8;
    --sch-primary-subtle: rgba(75, 108, 158, 0.12);
    --sch-success: #2e9e6e;
    --sch-danger: #d9534f;
    --sch-warning: #e8a838;
    --sch-info: #5b9bd5;
    --sch-card-radius: 12px;
    --sch-card-shadow: 0 2px 12px rgba(75, 108, 158, 0.08);
    --sch-card-shadow-hover: 0 8px 24px rgba(75, 108, 158, 0.14);
    --sch-text-muted: #6c7a89;
    --sch-border: #e8ecf1;
}

.sch-dash .sch-dash-title {
    color: #2c3e50;
    font-weight: 600;
}

.sch-dash .sch-dash-card {
    border: 1px solid var(--sch-border);
    border-radius: var(--sch-card-radius);
    box-shadow: var(--sch-card-shadow);
    background: #fff;
    transition: box-shadow 0.25s ease, transform 0.25s ease;
}

.sch-dash .sch-dash-card:hover {
    box-shadow: var(--sch-card-shadow-hover);
}

.sch-dash .sch-dash-card-header {
    padding: 1rem 1.25rem 0.5rem;
    border-bottom: none;
    background: transparent;
}

.sch-dash .sch-dash-card-header h5 {
    font-size: 0.95rem;
    font-weight: 600;
    color: #2c3e50;
    margin: 0;
}

.sch-dash .sch-dash-card-body {
    padding: 0.75rem 1.25rem 1.25rem;
}

/* Filter bar */
.sch-dash .sch-dash-filter {
    padding: 1rem 1.25rem;
    margin-bottom: 1.25rem;
}

.sch-dash .sch-dash-filter label {
    font-size: 0.72rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    color: var(--sch-text-muted);
    margin-bottom: 0.25rem;
}

.sch-dash .sch-dash-filter .form-select {
    font-size: 0.85rem;
    border-color: var(--sch-border);
    border-radius: 8px;
    padding: 0.4rem 2rem 0.4rem 0.75rem;
    color: #2c3e50;
}

.sch-dash .sch-dash-filter .form-select:focus {
    border-color: var(--sch-primary);
    box-shadow: 0 0 0 0.2rem rgba(75, 108, 158, 0.15);
}

.sch-dash .sch-dash-update {
    font-size: 0.8rem;
    color: var(--sch-text-muted);
}

.sch-dash .sch-dash-update strong {
    color: #2c3e50;
}

.sch-dash .btn-sch-refresh {
    background: var(--sch-primary);
    border-color: var(--sch-primary);
    color: #fff;
    border-radius: 8px;
    font-size: 0.85rem;
    padding: 0.45rem 1rem;
    transition: background 0.2s ease;
}

.sch-dash .btn-sch-refresh:hover {
    background: #3d5a82;
    border-color: #3d5a82;
    color: #fff;
}

.sch-dash .btn-sch-refresh .bi {
    transition: transform 0.4s ease;
}

.sch-dash .btn-sch-refresh.is-loading .bi {
    animation: sch-dash-spin 0.8s linear infinite;
}

@keyframes sch-dash-spin {
    from { transform: rotate(0deg); }
    to { transform: rotate(360deg); }
}

/* KPI cards */
.sch-dash .sch-dash-kpi {
    padding: 1.15rem 1.25rem;
    height: 100%;
    cursor: default;
}

.sch-dash .sch-dash-kpi:hover {
    transform: translateY(-3px);
}

.sch-dash .sch-dash-kpi-icon {
    width: 48px;
    height: 48px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.35rem;
    flex-shrink: 0;
}

.sch-dash .sch-dash-kpi-icon.primary { background: var(--sch-primary-subtle); color: var(--sch-primary); }
.sch-dash .sch-dash-kpi-icon.success { background: rgba(46, 158, 110, 0.12); color: var(--sch-success); }
.sch-dash .sch-dash-kpi-icon.warning { background: rgba(232, 168, 56, 0.12); color: var(--sch-warning); }
.sch-dash .sch-dash-kpi-icon.danger { background: rgba(217, 83, 79, 0.12); color: var(--sch-danger); }
.sch-dash .sch-dash-kpi-icon.info { background: rgba(91, 155, 213, 0.12); color: var(--sch-info); }

.sch-dash .sch-dash-kpi-value {
    font-size: 1.65rem;
    font-weight: 700;
    color: #2c3e50;
    line-height: 1.2;
}

.sch-dash .sch-dash-kpi-label {
    font-size: 0.78rem;
    color: var(--sch-text-muted);
    font-weight: 500;
    margin-top: 0.15rem;
}

.sch-dash .sch-dash-kpi-trend {
    font-size: 0.75rem;
    font-weight: 600;
    margin-top: 0.5rem;
}

.sch-dash .sch-dash-kpi-trend.up { color: var(--sch-success); }
.sch-dash .sch-dash-kpi-trend.down { color: var(--sch-danger); }
.sch-dash .sch-dash-kpi-trend.neutral { color: var(--sch-text-muted); }

/* Chart cards */
.sch-dash .sch-dash-chart-wrap {
    min-height: 320px;
}

.sch-dash .sch-dash-chart-wrap.sm {
    min-height: 280px;
}

/* Alert timeline */
.sch-dash .sch-dash-alerts {
    padding: 1.25rem;
}

.sch-dash .sch-dash-alerts-title {
    font-size: 1rem;
    font-weight: 600;
    color: #2c3e50;
    margin-bottom: 1rem;
}

.sch-dash .sch-dash-alert-item {
    display: flex;
    align-items: flex-start;
    gap: 0.85rem;
    padding: 0.85rem 1rem;
    border-radius: 10px;
    margin-bottom: 0.65rem;
    border-left: 4px solid transparent;
    transition: background 0.2s ease;
}

.sch-dash .sch-dash-alert-item:last-child {
    margin-bottom: 0;
}

.sch-dash .sch-dash-alert-item:hover {
    filter: brightness(0.98);
}

.sch-dash .sch-dash-alert-item.danger {
    background: rgba(217, 83, 79, 0.08);
    border-left-color: var(--sch-danger);
}

.sch-dash .sch-dash-alert-item.warning {
    background: rgba(232, 168, 56, 0.1);
    border-left-color: var(--sch-warning);
}

.sch-dash .sch-dash-alert-icon {
    width: 36px;
    height: 36px;
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1rem;
    flex-shrink: 0;
}

.sch-dash .sch-dash-alert-item.danger .sch-dash-alert-icon {
    background: rgba(217, 83, 79, 0.15);
    color: var(--sch-danger);
}

.sch-dash .sch-dash-alert-item.warning .sch-dash-alert-icon {
    background: rgba(232, 168, 56, 0.2);
    color: #c48a1a;
}

.sch-dash .sch-dash-alert-text {
    font-size: 0.88rem;
    color: #2c3e50;
    font-weight: 500;
    line-height: 1.4;
}

.sch-dash .sch-dash-alert-meta {
    font-size: 0.75rem;
    color: var(--sch-text-muted);
    margin-top: 0.15rem;
}

/* AI Insight */
.sch-dash .sch-dash-insight {
    padding: 1.25rem;
    background: linear-gradient(135deg, #f8fafc 0%, #eef2f7 100%);
    border: 1px solid var(--sch-border);
}

.sch-dash .sch-dash-insight-header {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    margin-bottom: 1rem;
}

.sch-dash .sch-dash-insight-avatar {
    width: 36px;
    height: 36px;
    border-radius: 10px;
    background: linear-gradient(135deg, var(--sch-primary) 0%, var(--sch-primary-light) 100%);
    display: flex;
    align-items: center;
    justify-content: center;
    color: #fff;
    font-size: 1.1rem;
}

.sch-dash .sch-dash-insight-header h5 {
    margin: 0;
    font-size: 1rem;
    font-weight: 600;
    color: #2c3e50;
}

.sch-dash .sch-dash-insight-header small {
    color: var(--sch-text-muted);
    font-size: 0.75rem;
}

.sch-dash .sch-dash-insight-item {
    display: flex;
    align-items: flex-start;
    gap: 0.65rem;
    padding: 0.75rem 1rem;
    background: #fff;
    border-radius: 10px;
    margin-bottom: 0.55rem;
    border: 1px solid var(--sch-border);
    font-size: 0.88rem;
    color: #3d4f5f;
    line-height: 1.45;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.sch-dash .sch-dash-insight-item:hover {
    border-color: var(--sch-primary-light);
    box-shadow: 0 2px 8px rgba(75, 108, 158, 0.1);
}

.sch-dash .sch-dash-insight-item:last-child {
    margin-bottom: 0;
}

.sch-dash .sch-dash-insight-item .insight-emoji {
    font-size: 1rem;
    flex-shrink: 0;
    margin-top: 1px;
}

/* Spacing */
.sch-dash .sch-dash-row {
    margin-bottom: 1.25rem;
}

.sch-dash .sch-dash-kpi-col {
    margin-bottom: 1rem;
}

/* Responsive */
@media (min-width: 1400px) {
    .sch-dash .sch-dash-kpi-value {
        font-size: 1.5rem;
    }
}

@media (max-width: 767.98px) {
    .sch-dash .sch-dash-filter .sch-dash-filter-actions {
        margin-top: 0.75rem;
        text-align: left !important;
    }

    .sch-dash .sch-dash-kpi-value {
        font-size: 1.4rem;
    }
}

/**
 * School Dashboard - ApexCharts mock data
 * Namespace: sch-dash
 */
(function () {
    "use strict";

    var PRIMARY = "#4b6c9e";
    var PRIMARY_LIGHT = "#6b8bb8";
    var SUCCESS = "#2e9e6e";
    var DANGER = "#d9534f";
    var WARNING = "#e8a838";
    var INFO = "#5b9bd5";
    var MUTED = "#adb0bb";
    var FACULTIES = ["CNTT", "Kinh t\u1ebf", "\u0110i\u1ec7n", "Du l\u1ecbch", "C\u01a1 kh\u00ed"];
    var MONTHS = ["T1", "T2", "T3", "T4", "T5", "T6", "T7", "T8", "T9", "T10", "T11", "T12"];

    var chartInstances = {};
    var baseChartOpts = {
        fontFamily: "inherit",
        foreColor: MUTED,
        toolbar: { show: false }
    };

    function formatNumber(val) {
        return val.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ".");
    }

    function destroyCharts() {
        var key;
        for (key in chartInstances) {
            if (chartInstances.hasOwnProperty(key) && chartInstances[key]) {
                chartInstances[key].destroy();
                chartInstances[key] = null;
            }
        }
    }

    function renderChart(id, options) {
        var el = document.querySelector(id);
        if (!el) {
            return;
        }
        if (chartInstances[id]) {
            chartInstances[id].destroy();
        }
        chartInstances[id] = new ApexCharts(el, options);
        chartInstances[id].render();
    }

    function getMockKpiData() {
        return {
            students: { value: "3.842", trend: "up", change: "4.2%", note: "so v\u1eddng k\u1ef3 tr\u01b0\u1edbc" },
            teachers: { value: "186", trend: "up", change: "2.1%", note: "so v\u1eddng n\u0103m tr\u01b0\u1edbc" },
            classes: { value: "128", trend: "neutral", change: "0%", note: "kh\u00f4ng \u0111\u1ed5i" },
            graduation: { value: "91.2%", trend: "up", change: "1.8%", note: "so v\u1eddng n\u0103m tr\u01b0\u1edbc" },
            warning: { value: "42", trend: "down", change: "8.5%", note: "gi\u1ea3m so v\u1eddng HK I" },
            debt: { value: "1.2 t\u1ef7", trend: "up", change: "5.0%", note: "c\u1ea7n theo d\u00f5i" },
            feeRate: { value: "85%", trend: "up", change: "3.2%", note: "so v\u1eddng th\u00e1ng tr\u01b0\u1edbc" },
            books: { value: "12.450", trend: "up", change: "6.7%", note: "t\u0103ng \u0111\u1ea7u s\u00e1ch m\u1edbi" }
        };
    }

    function updateKpiCards() {
        var data = getMockKpiData();
        var map = {
            "kpi-students": data.students,
            "kpi-teachers": data.teachers,
            "kpi-classes": data.classes,
            "kpi-graduation": data.graduation,
            "kpi-warning": data.warning,
            "kpi-debt": data.debt,
            "kpi-fee-rate": data.feeRate,
            "kpi-books": data.books
        };
        var key;
        for (key in map) {
            if (!map.hasOwnProperty(key)) {
                continue;
            }
            var card = document.getElementById(key);
            if (!card) {
                continue;
            }
            var item = map[key];
            var valueEl = card.querySelector(".sch-dash-kpi-value");
            var trendEl = card.querySelector(".sch-dash-kpi-trend");
            if (valueEl) {
                valueEl.textContent = item.value;
            }
            if (trendEl) {
                trendEl.className = "sch-dash-kpi-trend " + item.trend;
                var icon = item.trend === "up" ? "bi-arrow-up-short" : (item.trend === "down" ? "bi-arrow-down-short" : "bi-dash");
                trendEl.innerHTML = "<i class=\"bi " + icon + "\"></i> " + item.change + " <span class=\"fw-normal text-muted\">" + item.note + "</span>";
            }
        }
    }

    function renderFacultyDonut() {
        renderChart("#schDashChartFaculty", {
            series: [1024, 892, 756, 612, 558],
            chart: Object.assign({ height: 320, type: "donut" }, baseChartOpts),
            labels: FACULTIES,
            colors: [PRIMARY, SUCCESS, INFO, WARNING, "#8e9eab"],
            plotOptions: {
                pie: {
                    donut: {
                        size: "72%",
                        labels: {
                            show: true,
                            name: { show: true, fontSize: "13px", color: MUTED },
                            value: {
                                show: true,
                                fontSize: "22px",
                                fontWeight: 700,
                                color: "#2c3e50",
                                formatter: function (val) {
                                    return formatNumber(val);
                                }
                            },
                            total: {
                                show: true,
                                label: "T\u1ed5ng SV",
                                fontSize: "13px",
                                color: MUTED,
                                formatter: function (w) {
                                    var total = 0;
                                    var i;
                                    for (i = 0; i < w.globals.seriesTotals.length; i++) {
                                        total += w.globals.seriesTotals[i];
                                    }
                                    return formatNumber(total);
                                }
                            }
                        }
                    }
                }
            },
            dataLabels: { enabled: false },
            stroke: { show: true, width: 2, colors: ["#fff"] },
            legend: {
                show: true,
                position: "bottom",
                horizontalAlign: "center",
                fontSize: "13px"
            },
            tooltip: {
                y: {
                    formatter: function (val, opts) {
                        var total = opts.globals.seriesTotals.reduce(function (a, b) { return a + b; }, 0);
                        var pct = ((val / total) * 100).toFixed(1);
                        return formatNumber(val) + " SV (" + pct + "%)";
                    }
                }
            }
        });
    }

    function renderEnrollmentArea() {
        renderChart("#schDashChartEnrollment", {
            series: [
                { name: "H\u1ed3 s\u01a1 \u0111\u0103ng k\u00fd", data: [68, 82, 95, 110, 128, 142, 156, 168, 175, 188, 195, 210] },
                { name: "H\u1ed3 s\u01a1 nh\u1eadp h\u1ecdc", data: [52, 64, 78, 88, 102, 118, 124, 132, 140, 148, 155, 168] }
            ],
            chart: Object.assign({ height: 320, type: "area" }, baseChartOpts),
            colors: [PRIMARY, SUCCESS],
            dataLabels: { enabled: false },
            stroke: { curve: "smooth", width: 2.5 },
            fill: {
                type: "gradient",
                gradient: {
                    shadeIntensity: 1,
                    opacityFrom: 0.45,
                    opacityTo: 0.05,
                    stops: [0, 90, 100]
                }
            },
            legend: { show: true, position: "top", horizontalAlign: "right" },
            grid: { strokeDashArray: 3, borderColor: "rgba(0,0,0,0.05)" },
            xaxis: {
                categories: MONTHS,
                axisBorder: { show: false },
                axisTicks: { show: false }
            },
            yaxis: {
                tickAmount: 4,
                labels: {
                    formatter: function (val) {
                        return Math.round(val);
                    }
                }
            },
            tooltip: {
                y: {
                    formatter: function (val) {
                        return val + " h\u1ed3 s\u01a1";
                    }
                }
            }
        });
    }

    function renderGraduationLine() {
        renderChart("#schDashChartGraduation", {
            series: [{
                name: "T\u1ef7 l\u1ec7 t\u1ed1t nghi\u1ec7p",
                data: [86.5, 88.2, 89.1, 90.4, 91.2]
            }],
            chart: Object.assign({ height: 320, type: "line" }, baseChartOpts),
            colors: [PRIMARY],
            dataLabels: { enabled: false },
            stroke: { curve: "smooth", width: 3 },
            markers: {
                size: 5,
                colors: ["#fff"],
                strokeColors: PRIMARY,
                strokeWidth: 2,
                hover: { size: 7 }
            },
            grid: { strokeDashArray: 3, borderColor: "rgba(0,0,0,0.05)" },
            xaxis: {
                categories: ["2021", "2022", "2023", "2024", "2025"],
                axisBorder: { show: false },
                axisTicks: { show: false }
            },
            yaxis: {
                min: 80,
                max: 100,
                tickAmount: 4,
                labels: {
                    formatter: function (val) {
                        return val.toFixed(1) + "%";
                    }
                }
            },
            tooltip: {
                y: {
                    formatter: function (val) {
                        return val + "%";
                    }
                }
            }
        });
    }

    function renderStudyResultStacked() {
        renderChart("#schDashChartStudyResult", {
            series: [
                { name: "Gi\u1ecfi", data: [180, 165, 142, 128, 115] },
                { name: "Kh\u00e1", data: [320, 298, 265, 240, 220] },
                { name: "Trung b\u00ecnh", data: [280, 310, 295, 268, 252] },
                { name: "Y\u1ebfu", data: [45, 52, 48, 55, 62] }
            ],
            chart: Object.assign({ height: 320, type: "bar", stacked: true }, baseChartOpts),
            colors: [SUCCESS, PRIMARY, WARNING, DANGER],
            plotOptions: {
                bar: {
                    horizontal: false,
                    columnWidth: "55%",
                    borderRadius: 4
                }
            },
            dataLabels: { enabled: false },
            legend: { show: true, position: "top", horizontalAlign: "right" },
            grid: { strokeDashArray: 3, borderColor: "rgba(0,0,0,0.05)" },
            xaxis: {
                categories: FACULTIES,
                axisBorder: { show: false },
                axisTicks: { show: false }
            },
            tooltip: {
                y: {
                    formatter: function (val) {
                        return val + " sinh vi\u00ean";
                    }
                }
            }
        });
    }

    function renderRevenueArea() {
        renderChart("#schDashChartRevenue", {
            series: [
                { name: "\u0110\u00e3 thu", data: [180, 210, 195, 240, 220, 260, 230, 250, 280, 265, 290, 310] },
                { name: "C\u00f4ng n\u1ee3", data: [42, 38, 45, 40, 48, 35, 42, 38, 32, 36, 30, 28] }
            ],
            chart: Object.assign({ height: 320, type: "area" }, baseChartOpts),
            colors: [SUCCESS, DANGER],
            dataLabels: { enabled: false },
            stroke: { curve: "smooth", width: 2 },
            fill: {
                type: "gradient",
                gradient: {
                    shadeIntensity: 1,
                    opacityFrom: 0.4,
                    opacityTo: 0.06,
                    stops: [0, 90, 100]
                }
            },
            legend: { show: true, position: "top", horizontalAlign: "right" },
            grid: { strokeDashArray: 3, borderColor: "rgba(0,0,0,0.05)" },
            xaxis: {
                categories: MONTHS,
                axisBorder: { show: false },
                axisTicks: { show: false }
            },
            yaxis: {
                tickAmount: 4,
                labels: {
                    formatter: function (val) {
                        return val + " tr";
                    }
                }
            },
            tooltip: {
                y: {
                    formatter: function (val) {
                        return val + " tri\u1ec7u \u0111\u1ed3ng";
                    }
                }
            }
        });
    }

    function renderFeeRateRadial() {
        renderChart("#schDashChartFeeRate", {
            series: [85],
            chart: Object.assign({ height: 300, type: "radialBar", offsetY: 0 }, baseChartOpts),
            colors: [PRIMARY],
            plotOptions: {
                radialBar: {
                    startAngle: -135,
                    endAngle: 135,
                    hollow: { size: "65%" },
                    track: {
                        background: "rgba(75, 108, 158, 0.12)",
                        strokeWidth: "100%",
                        margin: 8
                    },
                    dataLabels: {
                        name: {
                            show: true,
                            fontSize: "14px",
                            color: MUTED,
                            offsetY: 24
                        },
                        value: {
                            offsetY: -8,
                            fontSize: "32px",
                            fontWeight: 700,
                            color: "#2c3e50",
                            formatter: function (val) {
                                return val + "%";
                            }
                        }
                    }
                }
            },
            stroke: { lineCap: "round" },
            labels: ["T\u1ef7 l\u1ec7 thu h\u1ecdc ph\u00ed"]
        });
    }

    function renderTeachingLoadBar() {
        renderChart("#schDashChartTeachingLoad", {
            series: [{
                name: "Gi\u1edd gi\u1ea3ng",
                data: [1240, 1180, 1120, 1080, 1020, 980, 920, 880, 840, 800]
            }],
            chart: Object.assign({ height: 320, type: "bar" }, baseChartOpts),
            colors: [PRIMARY],
            plotOptions: {
                bar: {
                    horizontal: true,
                    barHeight: "65%",
                    borderRadius: 4
                }
            },
            dataLabels: {
                enabled: true,
                style: { fontSize: "11px" },
                formatter: function (val) {
                    return val + " gi\u1edd";
                }
            },
            legend: { show: false },
            grid: { strokeDashArray: 3, borderColor: "rgba(0,0,0,0.05)" },
            xaxis: {
                categories: [
                    "CNTT", "Kinh t\u1ebf", "\u0110i\u1ec7n", "Du l\u1ecbch", "C\u01a1 kh\u00ed",
                    "X\u00e2y d\u1ef1ng", "Ngo\u1ea1i ng\u1eef", "Y t\u1ebf", "Lu\u1eadt", "M\u1ef9 thu\u1eadt"
                ],
                axisBorder: { show: false },
                axisTicks: { show: false }
            },
            tooltip: {
                y: {
                    formatter: function (val) {
                        return val + " gi\u1edd";
                    }
                }
            }
        });
    }

