    function bindEvents() {
        var refreshBtn = document.getElementById("schDashBtnRefresh");
        var filters = document.querySelectorAll(".sch-dash .sch-dash-filter-select");

        if (refreshBtn) {
            refreshBtn.addEventListener("click", function () {
                refreshBtn.classList.add("is-loading");
                setTimeout(function () {
                    loadDashboard();
                    refreshBtn.classList.remove("is-loading");
                }, 600);
            });
        }

        var i;
        for (i = 0; i < filters.length; i++) {
            filters[i].addEventListener("change", function () {
                loadDashboard();
            });
        }
    }

    document.addEventListener("DOMContentLoaded", function () {
        if (!document.querySelector(".sch-dash")) {
            return;
        }
        bindEvents();
        loadDashboard();
    });
})();

